mapper.select:
SELECT F.FORMNUM, F.FORMTITLE, F.FORMCONTENT, F.STATUS, F.REGDATE, M.STUDENTID, M.NAME, M.MAJOR, M.EMAIL1, M.EMAIL2, M.PHONE, C.CLUBNUM, C.CLUBNAME
FROM CLUBFORM F JOIN MEMBER M ON F.STUDENTID = M.STUDENTID JOIN CLUB C ON C.CLUBNUM = F.CLUBNUM
WHERE F.FORMNUM = #{formNum}

SELECT F.FORMNUM, F.FORMTITLE, F.FORMCONTENT, F.STATUS, F.REGDATE, M.STUDENTID, M.NAME, M.MAJOR, M.EMAIL1, M.EMAIL2, M.PHONE, C.CLUBNUM, C.CLUBNAME
FROM CLUBFORM F JOIN MEMBER M ON F.STUDENTID = M.STUDENTID JOIN CLUB C ON C.CLUBNUM = F.CLUBNUM
WHERE C.CLUBNUM = #{clubNum} AND M.STUDENTID = #{studentId}

mapper.update:
UPDATE CLUBFORM
SET STATUS = 2
WHERE FORMNUM = #{formNum}

UPDATE CLUBFORM
SET STATUS = 3
WHERE FORMNUM = #{formNum}
